package com.lendup.reservas.infrastructure.persistence;
import com.lendup.reservas.application.port.out.OutboxPort; import com.lendup.reservas.domain.event.EventEnvelope; import com.lendup.reservas.infrastructure.persistence.entity.OutboxEventEntity; import com.lendup.reservas.infrastructure.persistence.repository.OutboxJpaRepository; import org.springframework.stereotype.Component; import tools.jackson.databind.json.JsonMapper;
@Component public class OutboxJpaAdapter implements OutboxPort { private final OutboxJpaRepository repo; private final JsonMapper json; public OutboxJpaAdapter(OutboxJpaRepository r,JsonMapper j){repo=r;json=j;} public void append(EventEnvelope e){try{repo.save(new OutboxEventEntity(e.eventId(),"RESERVA",e.aggregateId(),e.eventType(),e.eventVersion(),e.aggregateVersion(),json.writeValueAsString(e.payload()),e.correlationId(),e.occurredAt()));}catch(Exception ex){throw new IllegalStateException("No se pudo serializar el evento",ex);}} }
